-file("src/data/exquisite_shelf_data.erl", 1).

-module(exquisite_shelf_data).

-export([get_map/1,
         get_fresh_unit/1,
         get_show_unit/1,
         get_shelf_lev/1,
         get_unit_pos/1,
         get_attr_ratio/1,
         get_reward/1,
         get_card_reward/1,
         shelf_lev_list/0,
         get_card_cost/1]).

-file("inc/common.hrl", 1).

-type p() :: bitstring().

-type z() :: non_neg_integer().

-type role_id() :: {pos_integer(), p(), z()}.

-type unit_id() :: {pos_integer(), pos_integer()}.

-type pos() :: {pos_integer(),
                non_neg_integer(),
                non_neg_integer()}.

-record(center,
        {ready = 0 :: 1 | 0,
         pid :: undefined | pid(),
         node :: undefined | atom(),
         center_platform = "" :: list(),
         center_zone_id = 0 :: non_neg_integer(),
         platform = <<>> :: bitstring(),
         zone_id = 0 :: non_neg_integer(),
         combine = [] :: [{bitstring(), non_neg_integer()}]}).

-record(notice_rec,
        {type = 11, digit_attr = [], str_attr = []}).

-file("src/data/exquisite_shelf_data.erl", 23).

